create table if not exists public.deal_discovery_sources (id uuid primary key default gen_random_uuid(), source_key text not null unique, display_name text not null, platform_type text not null default 'retail', integration_method text not null default 'official_api', integration_status text not null default 'not_connected' check (integration_status in ('not_connected','credentials_required','connected','paused','error')), is_enabled boolean not null default false, polling_interval_minutes integer not null default 360 check (polling_interval_minutes between 15 and 10080), last_checked_at timestamptz, last_success_at timestamptz, last_error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.deal_discovery_runs (id uuid primary key default gen_random_uuid(), source_id uuid references public.deal_discovery_sources(id) on delete set null, source_key text not null, run_status text not null check (run_status in ('running','success','partial','failed','skipped')), fetched_count integer not null default 0, normalized_count integer not null default 0, published_count integer not null default 0, review_count integer not null default 0, error_message text, started_at timestamptz not null default now(), finished_at timestamptz);
create table if not exists public.deal_discovery_items (id uuid primary key default gen_random_uuid(), source_key text not null, external_id text not null, content_hash text not null, title text not null, product_url text, image_url text, offer_price numeric, original_price numeric, currency text not null default 'INR', starts_at timestamptz, ends_at timestamptz, source_verified boolean not null default false, product_match_verified boolean not null default false, eligibility_verified boolean not null default false, confidence_score integer not null default 0 check (confidence_score between 0 and 100), review_status text not null default 'pending' check (review_status in ('pending','published','rejected','expired')), deal_id uuid references public.deals(id) on delete set null, raw_payload jsonb not null default '{}'::jsonb, last_seen_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(source_key,external_id));
create index if not exists deal_discovery_items_review_idx on public.deal_discovery_items(review_status,last_seen_at desc);
create index if not exists deal_discovery_runs_source_idx on public.deal_discovery_runs(source_key,started_at desc);
alter table public.deal_discovery_sources enable row level security;
alter table public.deal_discovery_runs enable row level security;
alter table public.deal_discovery_items enable row level security;
drop policy if exists discovery_sources_admin_read on public.deal_discovery_sources;
create policy discovery_sources_admin_read on public.deal_discovery_sources for select to authenticated using (exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()) and a.role in ('admin','editor')));
drop policy if exists discovery_runs_admin_read on public.deal_discovery_runs;
create policy discovery_runs_admin_read on public.deal_discovery_runs for select to authenticated using (exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()) and a.role in ('admin','editor')));
drop policy if exists discovery_items_admin_read on public.deal_discovery_items;
create policy discovery_items_admin_read on public.deal_discovery_items for select to authenticated using (exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()) and a.role in ('admin','editor')));
insert into public.deal_discovery_sources(source_key,display_name,integration_method,integration_status,is_enabled,polling_interval_minutes) values ('flipkart','Flipkart','official_affiliate_api','credentials_required',true,360),('amazon','Amazon India','approved_affiliate_feed','not_connected',false,360),('myntra','Myntra','approved_partner_feed','not_connected',false,360),('meesho','Meesho','merchant_or_approved_feed','not_connected',false,720) on conflict(source_key) do nothing;